'use strict';
window.AuraGuide = (()=>{
  function content(category='Camisas',sizes=['PP','P','M','G','GG','XGG']){const lower=['Calças','Jeans','Shorts','Bermudas','Saias'].includes(category);const dress=category==='Vestidos'||category==='Conjuntos';const table=Aura.el('table',{},Aura.el('caption',{text:'Referência demonstrativa — '+category+' (medidas do corpo em cm)'}),Aura.el('thead',{},Aura.el('tr',{},['Tamanho',...(lower?['Cintura','Quadril']:dress?['Busto','Cintura','Quadril']:['Peito / busto','Cintura'])].map(t=>Aura.el('th',{scope:'col',text:t})))));const body=Aura.el('tbody');sizes.forEach((s,i)=>{const n=/^\d+$/.test(s)?(Number(s)-34)/2:Math.max(0,['PP','P','M','G','GG','XGG'].indexOf(s));const waist=62+n*6,hip=88+n*6,chest=80+n*6;body.append(Aura.el('tr',{},Aura.el('th',{scope:'row',text:s}),...(lower?[waist+'–'+(waist+5),hip+'–'+(hip+5)]:dress?[chest+'–'+(chest+5),waist+'–'+(waist+5),hip+'–'+(hip+5)]:[chest+'–'+(chest+5),waist+'–'+(waist+5)]).map(v=>Aura.el('td',{text:v}))));});table.append(body);return Aura.el('div',{},Aura.el('p',{text:lower?'Meça a cintura na parte mais estreita e o quadril na parte mais larga, com a fita nivelada.':'Meça o peito ou busto na parte mais larga e a cintura na parte mais estreita, sem apertar a fita.'}),Aura.el('div',{class:'table-scroll'},table),Aura.el('p',{class:'warning',text:'Tabela ilustrativa. O caimento varia por peça. Antes da compra, peça ao vendedor as medidas reais do produto.'}));}
  document.addEventListener('DOMContentLoaded',()=>{const root=document.getElementById('guide-root');if(root){const s=Aura.el('select',{id:'guide-type','aria-label':'Tipo de peça'},Aura.categories.map(v=>Aura.el('option',{value:v,text:v}))),b=Aura.el('div');const show=()=>b.replaceChildren(content(s.value,['Calças','Jeans','Shorts','Bermudas','Saias'].includes(s.value)?['34','36','38','40','42','44','46','48']:undefined));s.addEventListener('change',show);root.append(s,b);show();}});return {content};
})();
